+      {session && comment.state === 'visible' && <MenuItem onClick={() => choose('report')}>Reportar</MenuItem>}
+      {summary.canManage && comment.state === 'visible' && <MenuItem onClick={() => choose('hide')}>Ocultar en mi contenido</MenuItem>}
