+   THEN RETURN '{"error":"rate_limited"}'; END IF;
+ IF op LIKE 'comment.%' AND op<>'comment.create' THEN
+   IF coalesce(payload->>'commentId','') !~ '^[0-9a-fA-F-]{36}$' THEN RETURN '{"error":"invalid"}'; END IF;
